def transform(grid):
    h, w = len(grid), len(grid[0])
    points = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                points.setdefault(grid[r][c], []).append((r, c))

    # Complete the lines to each point's two nearest aligned points.
    shapes = {}
    for color, dots in points.items():
        shape = set(dots)
        for r, c in dots:
            candidates = []
            for rr, cc in dots:
                dr, dc = rr - r, cc - c
                if (dr or dc) and (dr == 0 or dc == 0 or abs(dr) == abs(dc)):
                    candidates.append((dr * dr + dc * dc, rr, cc))

            if candidates:
                candidates.sort()
                cutoff = candidates[min(1, len(candidates) - 1)][0]
                for dist, rr, cc in candidates:
                    if dist <= cutoff:
                        dr, dc = rr - r, cc - c
                        steps = max(abs(dr), abs(dc))
                        sr = 0 if dr == 0 else (1 if dr > 0 else -1)
                        sc = 0 if dc == 0 else (1 if dc > 0 else -1)
                        for k in range(steps + 1):
                            shape.add((r + k * sr, c + k * sc))
        shapes[color] = shape

    out = [row[:] for row in grid]

    # Add completed source shapes, without overwriting input pixels.
    for color, shape in shapes.items():
        for r, c in shape:
            if out[r][c] == 0:
                out[r][c] = color

    # A lone adjacent dot marks a translated copy of another color's shape.
    copies = []
    for color, dots in points.items():
        if len(dots) != 1:
            continue
        r, c = dots[0]
        candidates = []
        for source, source_dots in points.items():
            if source == color or len(source_dots) < 2:
                continue
            for ar, ac in source_dots:
                dr, dc = r - ar, c - ac
                if max(abs(dr), abs(dc)) == 1:
                    candidates.append((dr * dr + dc * dc, source, dr, dc))
        if candidates:
            candidates.sort()
            _, source, dr, dc = candidates[0]
            copies.append((color, source, dr, dc))

    for color, source, dr, dc in copies:
