            if 0 <= rr < h and 0 <= cc < w and out[rr][cc] == 0:
                out[rr][cc] = color

    return out

def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    pattern_colors = [v for v in counts if v not in (bg, 0, 2)]
    if not pattern_colors:
        return [row[:] for row in grid]
    pattern_color = max(pattern_colors, key=lambda v: counts[v])

    pattern = {
        (r, c)
        for r in range(h) for c in range(w)
        if grid[r][c] == pattern_color
    }
    seed_cells = {
        (r, c)
        for r in range(h) for c in range(w)
        if grid[r][c] == 2
    }

    def components(cells):
        unseen = set(cells)
        result = []
        while unseen:
            start = min(unseen)
            unseen.remove(start)
            stack = [start]
            comp = {start}
            while stack:
                r, c = stack.pop()
                for q in ((r - 1, c), (r + 1, c),
                          (r, c - 1), (r, c + 1)):
                    if q in unseen:
                        unseen.remove(q)
                        comp.add(q)
                        stack.append(q)
            result.append(comp)
        return result

    def intervals(values):
        values = sorted(set(values))
        if not values:
            return []
        result = []
        lo = hi = values[0]
        for x in values[1:]:
            if x == hi + 1:
                hi = x
            else:
                result.append((lo, hi))
                lo = hi = x
        result.append((lo, hi))
        return result

    pattern_components = components(pattern)
    seeds = components(seed_cells)
    gates = []

    for comp in pattern_components:
        rows = {}
        cols = {}
        for r, c in comp:
            rows.setdefault(r, []).append(c)
            cols.setdefault(c, []).append(r)
        row_runs = {r: intervals(cs) for r, cs in rows.items()}

        # Gates with a horizontal closed bar and vertical rails.
        for r in sorted(rows):
            for left, right in row_runs[r]:
                if right - left + 1 < 5:
                    continue

                down_rails = []
                up_rails = []
                for c in range(left + 1, right):
                    length = 0
                    rr = r + 1
                    while (rr, c) in comp:
                        length += 1
                        rr += 1
                    if length >= 2:
                        down_rails.append((c, length))

                    length = 0
                    rr = r - 1
                    while (rr, c) in comp:
                        length += 1
                        rr -= 1
                    if length >= 2:
                        up_rails.append((c, length))

                # Open toward the south: the bump is just below the bar.
                for i in range(len(down_rails)):
                    for j in range(i + 1, len(down_rails)):
                        a, la = down_rails[i]
                        b, lb = down_rails[j]
                        if a >= b:
                            continue
                        inner = [c for c in range(a + 1, b)
                                 if (r + 1, c) in comp]
                        for x1, x2 in intervals(inner):
                            bump = {(r + 1, c) for c in range(x1, x2 + 1)}
                            gates.append({
                                "axis": "v", "move": (-1, 0),
                                "bump": bump,
                                "cols": set(range(x1, x2 + 1)),
                                "limit": max(r + la, r + lb),
                                "kind": "south",
                            })

                # Open toward the north: the bump is just above the bar.
                for i in range(len(up_rails)):
                    for j in range(i + 1, len(up_rails)):
                        a, la = up_rails[i]
                        b, lb = up_rails[j]
                        if a >= b:
                            continue
                        inner = [c for c in range(a + 1, b)
                                 if (r - 1, c) in comp]
                        for x1, x2 in intervals(inner):
                            bump = {(r - 1, c) for c in range(x1, x2 + 1)}
                            gates.append({
                                "axis": "v", "move": (1, 0),
                                "bump": bump,
                                "cols": set(range(x1, x2 + 1)),
                                "limit": min(r - la, r - lb),
                                "kind": "north",
