                            "bump_rows": bump_rows,
                            "side": side1,
                            "edge": edge,
                        })

    def roll(seed, move):
        dr, dc = move
        current = set(seed)
        path = set(current)
        steps = 0
        while True:
            nxt = {(r + dr, c + dc) for r, c in current}
            if any(r < 0 or r >= h or c < 0 or c >= w for r, c in nxt):
                return None
            hit = nxt & pattern
            if hit:
                return current, path, hit, steps
            current = nxt
            path.update(current)
            steps += 1

