        rs = [r for r, c in seed]
        cs = [c for r, c in seed]
        minr, maxr = min(rs), max(rs)
        minc, maxc = min(cs), max(cs)

        for gate in gates:
            if gate["axis"] == "v":
                if not set(range(minc, maxc + 1)).issubset(gate["cols"]):
                    continue
                if gate["kind"] == "south" and minr <= gate["limit"]:
                    continue
                if gate["kind"] == "north" and maxr >= gate["limit"]:
                    continue
            else:
                if not set(range(minr, maxr + 1)).issubset(gate["bump_rows"]):
                    continue
                if gate["side"] > 0 and minc <= gate["edge"]:
                    continue
                if gate["side"] < 0 and maxc >= gate["edge"]:
                    continue

            result = roll(seed, gate["move"])
            if result is None:
                continue
            final, path, hit, steps = result
            if steps > 0 and hit and hit.issubset(gate["bump"]):
                candidates.append((steps, si, final, path, gate["move"]))

    candidates.sort(key=lambda x: (x[0], x[1]))
    chosen = {}
    for item in candidates:
        if item[1] not in chosen:
            chosen[item[1]] = item

    out = [row[:] for row in grid]
    for r, c in seed_cells:
        out[r][c] = bg

    for _, _, final, path, _ in chosen.values():
        for r, c in path:
            out[r][c] = 0
        for r, c in final:
            out[r][c] = 2

    return out

