def transform(grid):
    from collections import Counter
    from functools import lru_cache

    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    result = [list(row) for row in grid]

    # Find the monochromatic 2x2 colored centers.
    seen = set()
    cores = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            if len(component) == 4:
                rows = [p[0] for p in component]
                cols = [p[1] for p in component]
                r0, r1 = min(rows), max(rows)
                c0, c1 = min(cols), max(cols)
                if r1 - r0 == 1 and c1 - c0 == 1:
                    cores.append({
                        "color": color, "r0": r0, "r1": r1,
                        "c0": c0, "c1": c1
                    })

    if not cores:
        return result

    palette = {core["color"] for core in cores}

    # The key row contains the ordered colors, separated by background cells.
    key_row = max(
        range(h),
        key=lambda r: (sum(v in palette for v in grid[r]), r)
    )
    sequence = [v for v in grid[key_row] if v in palette]

    row_levels = sorted({core["r0"] + core["r1"] for core in cores})
    col_levels = sorted({core["c0"] + core["c1"] for core in cores})
    row_rank = {v: i for i, v in enumerate(row_levels)}
    col_rank = {v: i for i, v in enumerate(col_levels)}

    # Determine each tile's outer frame boundary.
    for core in cores:
        r0, r1 = core["r0"], core["r1"]
        c0, c1 = core["c0"], core["c1"]
        mid_r, mid_c = (r0 + r1) // 2, (c0 + c1) // 2

        border = []
        for cc in range(c0, c1 + 1):
            if r0 > 0:
                border.append(grid[r0 - 1][cc])
            if r1 + 1 < h:
                border.append(grid[r1 + 1][cc])
        for rr in range(r0, r1 + 1):
            if c0 > 0:
                border.append(grid[rr][c0 - 1])
            if c1 + 1 < w:
                border.append(grid[rr][c1 + 1])

        frame_colors = [v for v in border
                        if v != background and v != core["color"]]
        if frame_colors:
            frame = Counter(frame_colors).most_common(1)[0][0]
        else:
            frame = grid[r0 - 1][mid_c]

        top, bottom = r0, r1
        left, right = c0, c1
        while top > 0 and grid[top - 1][mid_c] == frame:
            top -= 1
        while bottom + 1 < h and grid[bottom + 1][mid_c] == frame:
            bottom += 1
        while left > 0 and grid[mid_r][left - 1] == frame:
            left -= 1
        while right + 1 < w and grid[mid_r][right + 1] == frame:
            right += 1

        core["top"], core["bottom"] = top, bottom
        core["left"], core["right"] = left, right
        core["ri"] = row_rank[r0 + r1]
        core["ci"] = col_rank[c0 + c1]

    def adjacent(i, j):
        a, b = cores[i], cores[j]
        return ((a["ri"] == b["ri"] and abs(a["ci"] - b["ci"]) == 1) or
                (a["ci"] == b["ci"] and abs(a["ri"] - b["ri"]) == 1))

    # Match repeated colors to centers so consecutive entries follow neighboring tiles.
    n = len(cores)

    @lru_cache(None)
    def find_path(pos, last, used):
        if pos == len(sequence):
            return ()
        for i, core in enumerate(cores):
            if used & (1 << i) or core["color"] != sequence[pos]:
                continue
            if last != -1 and not adjacent(last, i):
                continue
            rest = find_path(pos + 1, i, used | (1 << i))
            if rest is not None:
                return (i,) + rest
        return None

    path = find_path(0, -1, 0)
    if path is None:
        return result

    # Extend each tile's color through the gap toward the next tile.
    for i, j in zip(path, path[1:]):
        a, b = cores[i], cores[j]
        color = a["color"]

        if a["ri"] == b["ri"]:
            if b["ci"] > a["ci"]:
                cols = range(a["right"] + 1, b["left"])
            else:
                cols = range(b["right"] + 1, a["left"])
            for rr in range(a["r0"], a["r1"] + 1):
                for cc in cols:
                    result[rr][cc] = color
        elif b["ri"] > a["ri"]:
            for rr in range(a["bottom"] + 1, b["top"]):
                for cc in range(a["c0"], a["c1"] + 1):
                    result[rr][cc] = color
        else:
            for rr in range(b["bottom"] + 1, a["top"]):
                for cc in range(a["c0"], a["c1"] + 1):
                    result[rr][cc] = color

    return result

