                            and (nr, nc) not in seen
                            and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            components.append((color, cells))

    frames = []
    for i, (color, cells) in enumerate(components):
        rmin = min(r for r, c in cells)
        rmax = max(r for r, c in cells)
        cmin = min(c for r, c in cells)
        cmax = max(c for r, c in cells)
        if rmax - rmin < 2 or cmax - cmin < 2:
            continue

        border = set()
        for c in range(cmin, cmax + 1):
            border.add((rmin, c))
            border.add((rmax, c))
        for r in range(rmin, rmax + 1):
            border.add((r, cmin))
            border.add((r, cmax))

        if set(cells) == border:
            frames.append((i, color, rmin, rmax, cmin, cmax, cells))

    frame_ids = {frame[0] for frame in frames}
    output = [[bg for _ in range(w)] for _ in range(h)]

    for _, color, _, _, _, _, cells in frames:
        for r, c in cells:
            output[r][c] = color

