        counts = {}
        for value in seq:
            if value:
                counts[value] = counts.get(value, 0) + 1
        return any(count >= 2 for count in counts.values())

    row_count = sum(repeated(row) for row in grid)
    col_count = sum(repeated([grid[r][c] for r in range(h)]) for c in range(w))
