    from collections import Counter, defaultdict

    g = [list(row) for row in grid]
    h, w = len(g), len(g[0])
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))

    # The multicolored connected component is the color lookup table.
    seen = set()
    mixed_components = []
    for r in range(h):
        for c in range(w):
            if g[r][c] == bg or (r, c) in seen:
                continue
            comp = set()
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                rr, cc = stack.pop()
                comp.add((rr, cc))
                for dr, dc in dirs:
                    nr, nc = rr + dr, cc + dc
                    if (0 <= nr < h and 0 <= nc < w and
                            g[nr][nc] != bg and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            if len({g[rr][cc] for rr, cc in comp}) > 1:
                mixed_components.append(comp)

    key_cells = set()
    if mixed_components:
        def key_score(comp):
            rs = [p[0] for p in comp]
            cs = [p[1] for p in comp]
            return (int(max(cs) - min(cs) == 1), len(comp),
                    len({g[r][c] for r, c in comp}), max(rs), -min(cs))

        key_cells = max(mixed_components, key=key_score)

    records = []
    if key_cells:
        r0 = min(r for r, c in key_cells)
        r1 = max(r for r, c in key_cells)
        c0 = min(c for r, c in key_cells)
        c1 = max(c for r, c in key_cells)
        if c1 == c0 + 1:
            for r in range(r0, r1 + 1):
                source, target = g[r][c0], g[r][c1]
                if source != bg:
                    records.append((source, target))

    mapping = {source: target for source, target in records}

    # Find monochromatic L triominoes outside the lookup table.
    seen = set(key_cells)
    l_shapes = defaultdict(list)
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color == bg or (r, c) in seen:
                continue
            comp = set()
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                rr, cc = stack.pop()
                comp.add((rr, cc))
                for dr, dc in dirs:
                    nr, nc = rr + dr, cc + dc
                    if (0 <= nr < h and 0 <= nc < w and
                            (nr, nc) not in seen and
                            (nr, nc) not in key_cells and
                            g[nr][nc] == color):
                        seen.add((nr, nc))
                        stack.append((nr, nc))

            if len(comp) == 3:
                top = min(rr for rr, cc in comp)
                left = min(cc for rr, cc in comp)
                if max(rr for rr, cc in comp) == top + 1 and \
                   max(cc for rr, cc in comp) == left + 1:
                    pattern = {(rr - top, cc - left) for rr, cc in comp}
                    missing = next(iter({(0, 0), (0, 1), (1, 0), (1, 1)} - pattern))
                    l_shapes[color].append({
                        "top": top, "left": left, "missing": missing,
                        "cells": comp
                    })

    def are_opposite_corners(a, b):
        if a["top"] > b["top"]:
            a, b = b, a
        if a["top"] == b["top"]:
            return False
        if a["left"] < b["left"]:
            return a["missing"] == (1, 1) and b["missing"] == (0, 0)
        if a["left"] > b["left"]:
            return a["missing"] == (1, 0) and b["missing"] == (0, 1)
        return False

    pairs_by_color = defaultdict(list)
    paired_cells = set()
    for color, shapes in l_shapes.items():
        for i in range(len(shapes)):
            for j in range(i + 1, len(shapes)):
                a, b = shapes[i], shapes[j]
                if are_opposite_corners(a, b):
                    pairs_by_color[color].append((a, b))
                    paired_cells.update(a["cells"])
                    paired_cells.update(b["cells"])

    def mapped_color(color):
        return bg if color == 0 else color

    out = [row[:] for row in g]

    # Recolor mapped objects that are not being used as paired L-corners.
    for r in range(h):
        for c in range(w):
            if ((r, c) not in key_cells and (r, c) not in paired_cells
                    and g[r][c] in mapping):
                out[r][c] = mapped_color(mapping[g[r][c]])

    # Draw each filled rectangle, processing table rows from bottom to top.
    for source, target in reversed(records):
        fill = mapped_color(target)
        for a, b in pairs_by_color.get(source, []):
            anchors = a["cells"] | b["cells"]
            cells = anchors
            r0 = min(r for r, c in cells)
            r1 = max(r for r, c in cells)
            c0 = min(c for r, c in cells)
            c1 = max(c for r, c in cells)
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    if (r, c) in key_cells:
                        out[r][c] = g[r][c]
                    elif (r, c) in anchors:
                        out[r][c] = g[r][c]
                    else:
                        out[r][c] = fill

    return out

