                             for r, c, v in cells]
                else:
                    nh, nw = sw, sh
                    moved = [(sw - 1 - c, r, v) for r, c, v in cells]
                moved = tuple(sorted(moved))
                key = (nh, nw, moved)
                if key not in used_shapes:
                    used_shapes.add(key)
                    result.append((nh, nw, moved))
        return result

    def assemble(allow_reflect):
        opts = [orientations(p, allow_reflect) for p in components]
        fixed = None
        for orient in opts[marked_id]:
            if any(v == 5 and r == 0 and c == 0
                   for r, c, v in orient[2]):
                fixed = orient
                break
        if fixed is None or fixed[0] > side or fixed[1] > side:
            return None

        board = [0] * (side * side)
        occupied = 0
        for r, c, v in fixed[2]:
            idx = r * side + c
            bit = 1 << idx
            if occupied & bit:
                return None
            occupied |= bit
            board[idx] = v

        remaining = sorted(
            (i for i in range(len(components)) if i != marked_id),
            key=lambda i: (components[i]["top"], components[i]["left"])
        )
        by_cell = [dict() for _ in remaining]

        for j, pid in enumerate(remaining):
            seen_placements = set()
            for oh, ow, cells in opts[pid]:
                if oh > side or ow > side:
                    continue
                for r0 in range(side - oh + 1):
                    for c0 in range(side - ow + 1):
                        pairs = tuple(sorted(
                            ((r0 + r) * side + c0 + c, v)
                            for r, c, v in cells
                        ))
                        mask = 0
                        for idx, _ in pairs:
                            mask |= 1 << idx
                        key = (mask, pairs)
                        if key in seen_placements:
                            continue
                        seen_placements.add(key)
                        placement = (mask, pairs)
                        for idx, _ in pairs:
                            by_cell[j].setdefault(idx, []).append(placement)

