        failed = set()

        def search(occ, used):
            if used == all_used:
                return occ == full
            state = (occ, used)
            if state in failed:
                return False

            best = None
            for idx in range(side * side):
                if (occ >> idx) & 1:
                    continue
                choices = []
                for j in range(len(remaining)):
                    if (used >> j) & 1:
                        continue
                    for placement in by_cell[j].get(idx, ()):
                        if not (placement[0] & occ):
                            choices.append((j, placement))
                if not choices:
                    failed.add(state)
                    return False
                if best is None or len(choices) < len(best):
                    best = choices
                    if len(best) == 1:
                        break

