                for idx, v in pairs:
                    board[idx] = v
                if search(occ | mask, used | (1 << j)):
                    return True
                for idx, _ in pairs:
                    board[idx] = 0

            failed.add(state)
            return False

        if search(occupied, 0):
            return [board[r * side:(r + 1) * side] for r in range(side)]
        return None

    result = assemble(False)
    if result is not None:
        return result
    result = assemble(True)
    if result is not None:
        return result
    return [[0] * side for _ in range(side)]

