        best_key = None
        best_data = None

        for a in range(n):
            for b in range(a + 1, n):
                if a == 0 and b == n - 1:
                    continue
                if line[a] != line[b]:
                    continue

                length = b - a - 1
                if length < 8:
                    continue

                max_period = min(8, length // 3)
                for period in range(1, max_period + 1):
                    motif = []
                    for residue in range(period):
                        counts = {}
                        order = []
                        for t in range(residue, length, period):
                            value = line[a + 1 + t]
                            if value not in counts:
                                counts[value] = 0
                                order.append(value)
                            counts[value] += 1
                        motif.append(max(order, key=lambda value: counts[value]))

