            cur = [row[:] for row in base]
            for _ in range(4):
                result.add(tuple(tuple(row) for row in cur))
                cur = [[cur[2 - j][i] for j in range(3)] for i in range(3)]
        return result

    keys = []
    for x in xs:
        key = tile_at(1, x)
        if any(cell != 8 for row in key for cell in row):
            keys.append(variants(key))

    ys = [8, 13, 18, 23]
    hits = [[False] * 4 for _ in range(4)]

    for ri, y in enumerate(ys):
        for ci, x in enumerate(xs):
            target = tuple(tuple(row) for row in tile_at(y, x))
            hits[ri][ci] = any(target in key_variants for key_variants in keys)

    for ri, y in enumerate(ys):
        for ci, x in enumerate(xs):
            if hits[ri][ci]:
                for r in range(max(0, y - 1), min(h, y + 4)):
                    for c in range(max(0, x - 1), min(w, x + 4)):
                        if out[r][c] == 8:
                            out[r][c] = 3

    aligned = (
        any(all(hits[r][c] for c in range(4)) for r in range(4))
        or any(all(hits[r][c] for r in range(4)) for c in range(4))
    )

    if aligned:
        for r in range(min(5, h)):
            for c in range(w):
                if out[r][c] == 8:
                    out[r][c] = 3

    bottom_color = 3 if aligned else 2
    for r in range(28, min(30, h)):
        for c in range(w):
            out[r][c] = bottom_color

    return out

def transform(grid):
    from collections import Counter, defaultdict, deque

    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]

    # Find solid square objects of non-background colors.
    seen = set()
    blocks = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.pop()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and
                            (nx, ny) not in seen and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            rs = [x for x, _ in cells]
            cs = [y for _, y in cells]
            bh, bw = max(rs) - min(rs) + 1, max(cs) - min(cs) + 1
            if bh == bw and bh >= 2 and len(cells) == bh * bw:
                blocks.append({"color": color, "cells": cells})

    if not blocks:
        return out

    block_counts = Counter(b["color"] for b in blocks)
    terminal_colors = [color for color, n in block_counts.items() if n == 2]
    if terminal_colors:
        terminal_color = terminal_colors[0]
    else:
        terminal_color = min(block_counts, key=block_counts.get)

    other_colors = [c for c in block_counts if c != terminal_color]
    if not other_colors:
        return out
    object_color = max(other_colors, key=lambda c: block_counts[c])

    # The thin line color is the most common remaining non-background color.
    line_colors = [
        c for c in counts
        if c != background and c not in block_counts
    ]
    if not line_colors:
        return out
    line_color = max(line_colors, key=lambda c: counts[c])

    # Connected components of the thin line, using diagonal connectivity.
    wire_id = {}
    wires = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != line_color or (r, c) in wire_id:
                continue
            idx = len(wires)
            q = [(r, c)]
            wire_id[(r, c)] = idx
            cells = []
            while q:
                x, y = q.pop()
                cells.append((x, y))
                for dx in (-1, 0, 1):
                    for dy in (-1, 0, 1):
                        if dx == 0 and dy == 0:
                            continue
                        nx, ny = x + dx, y + dy
                        if (0 <= nx < h and 0 <= ny < w and
                                grid[nx][ny] == line_color and
                                (nx, ny) not in wire_id):
                            wire_id[(nx, ny)] = idx
                            q.append((nx, ny))
            wires.append(cells)

    # Build a graph alternating between square objects and line components.
    adj = defaultdict(set)
    for i in range(len(blocks)):
        adj[("b", i)]
    for i in range(len(wires)):
        adj[("w", i)]

    for bi, block in enumerate(blocks):
        for r, c in block["cells"]:
            for dx in (-1, 0, 1):
                for dy in (-1, 0, 1):
                    if dx == 0 and dy == 0:
                        continue
                    nr, nc = r + dx, c + dy
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) in wire_id:
                        wi = wire_id[(nr, nc)]
                        adj[("b", bi)].add(("w", wi))
                        adj[("w", wi)].add(("b", bi))

    terminals = [i for i, b in enumerate(blocks)
                 if b["color"] == terminal_color]
    if len(terminals) != 2:
        return out

    start, goal = ("b", terminals[0]), ("b", terminals[1])
    queue = deque([start])
    parent = {start: None}
    while queue and goal not in parent:
        node = queue.popleft()
        for nxt in sorted(adj[node]):
            if nxt not in parent:
                parent[nxt] = node
                queue.append(nxt)

    if goal not in parent:
        return out

    path = []
    node = goal
    while node is not None:
        path.append(node)
        node = parent[node]

    for kind, idx in path:
        if kind == "w":
            for r, c in wires[idx]:
                out[r][c] = 5
        elif blocks[idx]["color"] == object_color:
            for r, c in blocks[idx]["cells"]:
                out[r][c] = 3

    return out
